ALTER TABLE "webhook_calls" DROP CONSTRAINT "webhook_calls_result_consistency";--> statement-breakpoint
ALTER TABLE "webhook_calls" ADD CONSTRAINT "webhook_calls_result_consistency" CHECK (("webhook_calls"."outcome" = 'succeeded' AND "webhook_calls"."request_id" IS NOT NULL AND "webhook_calls"."response_value" IS NOT NULL AND "webhook_calls"."response_value" BETWEEN 0 AND 999999 AND "webhook_calls"."error_name" IS NULL AND "webhook_calls"."error_message" IS NULL) OR ("webhook_calls"."outcome" = 'failed' AND "webhook_calls"."request_id" IS NULL AND "webhook_calls"."response_value" IS NULL AND "webhook_calls"."error_name" IS NOT NULL AND "webhook_calls"."error_message" IS NOT NULL));